// AlleleServiceHandler is an implementation of the tooling.allele.v1.AlleleService service.
type AlleleServiceHandler interface {
	// Repositories
	ListRepositories(context.Context, *connect.Request[v1.ListRepositoriesRequest]) (*connect.Response[v1.ListRepositoriesResponse], error)
	CreateRepository(context.Context, *connect.Request[v1.CreateRepositoryRequest]) (*connect.Response[v1.Repository], error)
	GetRepository(context.Context, *connect.Request[v1.GetRepositoryRequest]) (*connect.Response[v1.Repository], error)
	// Worktrees -- opening one is observed, not commanded: the first push of a new branch is what
	// creates its row (Phase 7). GetWorktreeOverlap backs the pairwise matrix.
	ListWorktrees(context.Context, *connect.Request[v1.ListWorktreesRequest]) (*connect.Response[v1.ListWorktreesResponse], error)
	GetWorktreeOverlap(context.Context, *connect.Request[v1.GetWorktreeOverlapRequest]) (*connect.Response[v1.GetWorktreeOverlapResponse], error)
	CloseWorktree(context.Context, *connect.Request[v1.CloseWorktreeRequest]) (*connect.Response[v1.CloseWorktreeResponse], error)
	// Changes -- a Change is the live, continuously-reindexed diff of one worktree's branch
	// against its base. EnqueueMerge enters the merge queue; it does not merge immediately -- see
	// the plan's "Agent worktrees are branches, and verification is queue-gated" section.
	ListChanges(context.Context, *connect.Request[v1.ListChangesRequest]) (*connect.Response[v1.ListChangesResponse], error)
	GetChange(context.Context, *connect.Request[v1.GetChangeRequest]) (*connect.Response[v1.Change], error)
	RebaseChange(context.Context, *connect.Request[v1.RebaseChangeRequest]) (*connect.Response[v1.Change], error)
	EnqueueMerge(context.Context, *connect.Request[v1.EnqueueMergeRequest]) (*connect.Response[v1.MergeQueueEntry], error)
	// Merge queue
	ListMergeQueue(context.Context, *connect.Request[v1.ListMergeQueueRequest]) (*connect.Response[v1.ListMergeQueueResponse], error)
	HoldMergeQueueEntry(context.Context, *connect.Request[v1.HoldMergeQueueEntryRequest]) (*connect.Response[v1.MergeQueueEntry], error)
	ResumeMergeQueueEntry(context.Context, *connect.Request[v1.ResumeMergeQueueEntryRequest]) (*connect.Response[v1.MergeQueueEntry], error)
	// Live feed -- backs the symbol-changes drawer and the queue's own live status. Dedicated
	// streaming RPC, not a Catalyst Consume subscription -- same reasoning as Relay's
	// WatchTranscript; see the plan's Decisions.
	WatchChanges(context.Context, *connect.Request[v1.WatchChangesRequest], *connect.ServerStream[v1.SymbolChangeEvent]) error
	// NotifyPush is called by the post-receive hook (cmd/post-receive-hook), once per accepted ref
	// update -- unlike CheckPushPermission's pre-receive hook, post-receive runs *after* objects are
	// committed to the real object store, which is what makes it safe to diff here (pre-receive's
	// own quarantined objects are only visible inside the hook's own process, not this server's).
	// Not called by UI/API clients. Publishes tooling.allele.v1.SymbolChanged for every symbol-level
	// change the push introduced (see Telemetry).
	NotifyPush(context.Context, *connect.Request[v1.NotifyPushRequest]) (*connect.Response[v1.NotifyPushResponse], error)
	// Provenance
	GetProvenance(context.Context, *connect.Request[v1.GetProvenanceRequest]) (*connect.Response[v1.Provenance], error)
	ListPathPermissions(context.Context, *connect.Request[v1.ListPathPermissionsRequest]) (*connect.Response[v1.ListPathPermissionsResponse], error)
	SetPathPermissions(context.Context, *connect.Request[v1.SetPathPermissionsRequest]) (*connect.Response[v1.SetPathPermissionsResponse], error)
	// CheckPushPermission is called by the pre-receive hook installed in every bare repo (see
	// store.go's installHook), not by UI/API clients -- modeled as an ordinary RPC rather than a
	// separate ad hoc endpoint, consistent with how every other operation in this domain is
	// represented, and reachable at the same address the hook already runs alongside (localhost).
	// On an allowed push it also records a Provenance row for ref/new_commit_sha (R4.1) -- one
	// round trip from the hook rather than two, since the hook only ever needs this check-and-record
	// done together, never separately.
	CheckPushPermission(context.Context, *connect.Request[v1.CheckPushPermissionRequest]) (*connect.Response[v1.CheckPushPermissionResponse], error)
	// Signing keys -- humans register their own (see the plan's Decisions); agents/evolution runs
	// never call these, since Allele mints and holds their keys itself.
	RegisterSigningKey(context.Context, *connect.Request[v1.RegisterSigningKeyRequest]) (*connect.Response[v1.SigningKey], error)
	ListSigningKeys(context.Context, *connect.Request[v1.ListSigningKeysRequest]) (*connect.Response[v1.ListSigningKeysResponse], error)
	RevokeSigningKey(context.Context, *connect.Request[v1.RevokeSigningKeyRequest]) (*connect.Response[v1.RevokeSigningKeyResponse], error)
	// Linkage manifest
	GetLinkageManifest(context.Context, *connect.Request[v1.GetLinkageManifestRequest]) (*connect.Response[v1.LinkageManifest], error)
	DiffLinkageManifest(context.Context, *connect.Request[v1.DiffLinkageManifestRequest]) (*connect.Response[v1.DiffLinkageManifestResponse], error)
	SetBreakingChangePolicy(context.Context, *connect.Request[v1.SetBreakingChangePolicyRequest]) (*connect.Response[v1.LinkageManifest], error)
	ApproveLinkageChange(context.Context, *connect.Request[v1.ApproveLinkageChangeRequest]) (*connect.Response[v1.ApproveLinkageChangeResponse], error)
}

